void setup() {
  // Configura el pin 13 como salida (Se ejecuta 1 sola vez)
  pinMode(13, OUTPUT);
}

void loop() {
  // Se ejecuta en bucle sin detenerse
  digitalWrite(13, HIGH);
  delay(1000);
  digitalWrite(13, LOW);
  delay(1000);
}

int pinLED = 13;          // Guarda el número del pin
int tiempoPausa = 500;     // Tiempo de retardo en milisegundos

void setup() {
  pinMode(pinLED, OUTPUT);
}

void loop() {
  digitalWrite(pinLED, HIGH);
  delay(tiempoPausa);
  digitalWrite(pinLED, LOW);
  delay(tiempoPausa);
}

const int pinBoton = 2; // Pin de entrada
const int pinLED = 13;  // Pin de salida

void setup() {
  pinMode(pinBoton, INPUT); // Configurado como Entrada
  pinMode(pinLED, OUTPUT);  // Configurado como Salida
}

int ledPin = 13;

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  digitalWrite(ledPin, HIGH); // Enciende el LED
  delay(1000);                // Espera 1 segundo
  digitalWrite(ledPin, LOW);  // Apaga el LED
  delay(1000);                // Espera 1 segundo
}

const int pinBoton = 2;
const int pinLED = 13;

void setup() {
  pinMode(pinBoton, INPUT);
  pinMode(pinLED, OUTPUT);
}

void loop() {
  int estado = digitalRead(pinBoton);

  if (estado == HIGH) {
    digitalWrite(pinLED, HIGH); // Enciende al presionar
  } else {
    digitalWrite(pinLED, LOW);  // Apaga al soltar
  }
}
